[URL Rewrite]
request if ${url} ~= /^https?:\/\/mpos-pic\.helipay\.com\/upload\/images\/advertisment\/image/i then reject(404)

[Rule]
DOMAIN-KEYWORD,mpos-pic.helipay.com,REJECT

[MITM]
hostname = %APPEND% mpos-pic.helipay.com
